function ALL_RACE_DAMAGE(e) {
  return [
    { id: BONUSID.DMG_FORMLESS_PERCENT, value: e },
    { id: BONUSID.DMG_UNDEAD_PERCENT, value: e },
    { id: BONUSID.DMG_BRUTE_PERCENT, value: e },
    { id: BONUSID.DMG_PLANT_PERCENT, value: e },
    { id: BONUSID.DMG_INSECT_PERCENT, value: e },
    { id: BONUSID.DMG_FISH_PERCENT, value: e },
    { id: BONUSID.DMG_DEMON_PERCENT, value: e },
    { id: BONUSID.DMG_DEMI_HUMAN_PERCENT, value: e },
    { id: BONUSID.DMG_ANGEL_PERCENT, value: e },
    { id: BONUSID.DMG_DRAGON_PERCENT, value: e },
  ];
}
